import {buretteDiagram} from './model-diagrams.js?v=20261023-physicscomplete01';
import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export function showTitration(kind,t=null,reveal=false,result=null){if(kind==='strength'){const partial=t?.ionisation==='partial';renderDiagram('Ionisation ≠ concentration','Qualitative particle sketch',`<div class="inventory-board"><span class="eyebrow">${t?.name||'ACID IN AQUEOUS SOLUTION'}</span><div class="acid-particles" role="img" aria-label="Qualitative ${partial?'partial':'complete'} ionisation: I symbols represent ionised acid units and M symbols unionised molecules">${Array.from({length:12},(_,i)=>`<span class="${partial&&i>2?'molecule':'ion'}">${partial&&i>2?'M':'I'}</span>`).join('')}</div><p class="diagram-caption">I: ionised acid unit · M: unionised molecule. Numbers are illustrative; not measured dissociation fractions or calculated pH.</p><p class="inventory-outcome">${reveal?`${t.strength} acid · ${t.relative} versus reference`:'Use degree of ionisation and amount per volume separately'}</p><p class="diagram-caption">The supplied pH pair is a separate comparison; this sketch does not calculate pH from concentration.</p></div>`,'STRENGTH / CONCENTRATION / PH ARE DISTINCT');return;}
renderDiagram('Read initial and final levels','Titre = final − initial',buretteDiagram(t,reveal,result),'SCHOOL PRACTICAL PREPARATION · NOT FULFILMENT');}
